+package com.example.customers.domain;
+
+import java.text.Normalizer;
+import java.util.Arrays;
+import java.util.EnumSet;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.regex.Pattern;
+
+/**
+ * A filter understood by {@link CustomerRepository}.
+ *
+ * @param name     free text; split on whitespace, every term must appear in the
+ *                 first or last name, ignoring case and accents. Blank matches all.
+ * @param statuses the statuses to show; empty matches every status
+ */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) {
+
+    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());
+
+    private static final Pattern MARKS = Pattern.compile("\\p{M}+");
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+");
+
+    public CustomerFilter {
+        name = name == null ? "" : name.strip();
+        statuses = (statuses == null || statuses.isEmpty())
+                ? Set.of()
+                : Set.copyOf(EnumSet.copyOf(statuses));
+    }
+
+    public boolean isEmpty() {
+        return name.isEmpty() && statuses.isEmpty();
+    }
+
+    /** The folded search terms; empty when there is no name filter. */
+    public List<String> nameTerms() {
+        String folded = fold(name).strip();
+        return folded.isEmpty() ? List.of() : Arrays.asList(WHITESPACE.split(folded));
+    }
+
+    /** Lower-cases and strips accents, so matching ignores both. */
+    public static String fold(String text) {
+        String decomposed = Normalizer.normalize(text, Normalizer.Form.NFD);
+        return MARKS.matcher(decomposed).replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
