+            totalCount = customerService.count();
+        }
+        summary.setText("Showing " + matchingCount + " of " + totalCount);
+        dataView.refreshAll();
+        if (updateUrl) {
+            writeUrl(newFilter);
+        }
+    }
+
+    private CustomerFilter currentFilter() {
+        return filter == null ? CustomerFilter.EMPTY : filter;
+    }
+
+    /**
+     * The grid's count callback. The filter's count was just asked of the
+     * backend when the filter was applied, so the grid reuses that answer
+     * rather than run the same count query a second time.
+     */
+    private int countMatching() {
+        if (filter == null) {
+            return customerService.count(CustomerFilter.EMPTY);
+        }
+        return matchingCount;
+    }
+
+    private void writeUrl(CustomerFilter newFilter) {
+        getUI().ifPresent(ui -> {
+            // Replace rather than push: typing must not add a history entry per keystroke.
+            // This does what History.replaceState(state, url, false) does, except that
+            // it keeps the commas of the status list readable instead of re-encoding them.
+            String query = toQueryString(newFilter);
+            if (ui.getSession().getConfiguration().isReactEnabled()) {
+                ui.getPage().executeJs("window.dispatchEvent(new CustomEvent('vaadin-navigate', "
+                        + "{ detail: { state: null, url: $0, replace: true, callback: false } }));",
+                        query.isEmpty() ? "" : "?" + query);
+            } else {
+                ui.getPage().executeJs("window.history.replaceState(window.history.state, '', $0);",
+                        query.isEmpty() ? "." : "./?" + query);
+            }
+        });
+    }
+
+    /** The filter as a query string, without the leading {@code ?}; empty for an empty filter. */
+    static String toQueryString(CustomerFilter filter) {
+        List<String> parts = new ArrayList<>();
+        if (!filter.name().isEmpty()) {
+            parts.add(NAME_PARAMETER + "="
+                    + URLEncoder.encode(filter.name(), StandardCharsets.UTF_8).replace("+", "%20"));
+        }
+        if (!filter.statuses().isEmpty()) {
+            parts.add(STATUS_PARAMETER + "=" + EnumSet.copyOf(filter.statuses()).stream()
+                    .map(CustomerStatus::name)
+                    .collect(Collectors.joining(",")));
+        }
+        return String.join("&", parts);
+    }
+
+    static Set<CustomerStatus> parseStatuses(List<String> values) {
+        List<CustomerStatus> statuses = new ArrayList<>();
+        values.stream()
+                .flatMap(value -> Arrays.stream(value.split(",")))
+                .map(value -> value.strip().toUpperCase(Locale.ROOT))
+                .filter(value -> !value.isEmpty())
+                .forEach(value -> Arrays.stream(CustomerStatus.values())
+                        .filter(status -> status.name().equals(value))
+                        .forEach(statuses::add));
+        return statuses.isEmpty() ? Set.of() : EnumSet.copyOf(statuses);
     }

