+        PlaywrightAssertions.assertThat(summary).hasText("Showing 500 of 500");
+        int historyLength = ((Number) page.evaluate("history.length")).intValue();
+
+        queryLog.clear();
+        page.locator("vaadin-text-field input").pressSequentially("josephine",
+                new Locator.PressSequentiallyOptions().setDelay(80));
+        PlaywrightAssertions.assertThat(summary).hasText(Pattern.compile("Showing [1-9]\\d* of 500"));
+        PlaywrightAssertions.assertThat(page).hasURL(Pattern.compile(".*/\\?name=josephine$"));
+        page.waitForTimeout(1000);
+        System.out.println("pages=" + queryLog.pageQueries() + " counts=" + queryLog.countQueries());
